const temas = [
  "cómo empezar a invertir con poco dinero",
  "errores financieros que te mantienen pobre",
  "qué es el interés compuesto y por qué te cambia la vida",
  "cómo crear tu primer fondo de emergencia",
  "diferencia entre activos y pasivos que nadie te explica",
  "cómo los ricos piensan diferente sobre el dinero",
  "inversiones que puedes hacer desde tu celular hoy"
];

const indice = new Date().getDate() % temas.length;
return [{ json: { tema: temas[indice] } }];

const { execSync } = require('child_process');

const texto = $('HTTP Request').item.json.response;
const fecha = new Date().toISOString().slice(0,10).replace(/-/g,'');
const archivo = `/tmp/shorts/audio_${fecha}.mp3`;

// Guardar texto en archivo temporal para evitar problemas con caracteres especiales
const fs = require('fs');
fs.writeFileSync('/tmp/shorts/texto_temp.txt', texto);

// Ejecutar edge-tts
execSync(`/home/ubuntu/.local/bin/edge-tts --voice es-ES-AlvaroNeural --text-file /tmp/shorts/texto_temp.txt --write-media ${archivo}`);

return [{ json: { archivo, texto, fecha } }];

